using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedAnchorCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Enemy/CorruptedAnchorCustomDescription", order = 0)]
public class CorruptedAnchorCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string firstArgument = (battleAction as CorruptedAnchorAction).CorruptAction.GetActionDescription(-1).RemoveLast();
		return base.localizationManager.GetLocalizedWhereX(firstArgument, y: false, GetRawLocalizedDescription(battleAction));
	}
}
